                /** Třídění výchozího profilu pro daný číselník */
                trideniVychozihoProfilu() {
                    const Content = this;
                    let profil;
                    if (Content.ciselnikDto) {
                        // různé třídění dle typu číselníku
                        switch (Content.idCiselniku) {
                            case 37 /* Gordic.Pam.Interface.CiselnikEnum.slozkyMzdyLegislativa */:
                                profil = {
                                    sort: "char_4,int_1,int_2,date_1"
                                };
                                break;
                            case 14 /* Gordic.Pam.Interface.CiselnikEnum.PlatoveTabulkyATarify */:
                                profil = {
                                    sort: "int_1,int_2,int_3,date_1"
                                };
                                break;
                            case 11 /* Gordic.Pam.Interface.CiselnikEnum.pamckza */:
                                profil = {
                                    sort: "char_1"
                                };
                                break;
                            case 12 /* Gordic.Pam.Interface.CiselnikEnum.pamcodp */:
                                profil = {
                                    sort: "int_1,int_2"
                                };
                                break;
                            default:
                                profil = {
                                    sort: "int_1,int_3"
                                };
                                break;
                        }
                    }
                    return profil;
                }
