/// <summary>
/// Administrace - Kalendáře
/// </summary>
var Gordic;
(function (Gordic) {
    var Pam;
    (function (Pam) {
        var WebClient;
        (function (WebClient) {
            var GKalendarFun;
            (function (GKalendarFun) {
                /** Zobrazí kalendář s událostmi (dny pracovní, nepracovní a svátky)
                 *  @param {GContent} cnt kontext
                 *  @param {JQuery<HTMLElement>} contentDiv element, ke kterému se připojuje výsledný kalendář
                 *  @param {Interface.GKalendarHlavickaDto} kalendarHlavickaDto DTO s daty hlavičky kalendáře
                 *  @param {Pam.Interface.GKalPracHodPerDto[]} planPeriodyDtos? pole DTO s plánem dnů periody (nepovinné)
                 */
                function zobrazKalendar(cnt, contentDiv, kalendarHlavickaDto, planPeriodyDtos) {
                    const def = $.Deferred();
                    const guid = Pam.CreateGuid();
                    cnt.beginOperation({ id: guid });
                    if (planPeriodyDtos) { // je plán
                        udalostiKalendare(kalendarHlavickaDto, planPeriodyDtos)
                            .then((udalosti) => {
                            // inicializační datumy
                            const initialDate = Pam.toDate(kalendarHlavickaDto.dat_plan_od);
                            const minDate = parseDate(kalendarHlavickaDto.dat_plan_od);
                            const minDateStr = GKalendarFun.dateWithoutTimezone(minDate);
                            const maxDate = parseDate(kalendarHlavickaDto.dat_plan_do);
                            const maxDateStr = GKalendarFun.dateWithoutTimezone(maxDate);
                            // widget kalendáře
                            const kalendar = $.newDiv("kalendarDlePlanu")
                                .appendTo(contentDiv)
                                .gcalendar({
                                initialDate: initialDate,
                                minDate: minDateStr,
                                maxDate: maxDateStr,
                                mode: "content",
                                filterButton: false,
                                //eventclick(element, data, inlinedialog) {
                                //}
                            })
                                .gcalendar("addEvent", udalosti);
                            def.resolve(kalendar);
                        })
                            .always(() => {
                            cnt.endOperation(guid);
                        });
                    }
                    else { // není plán
                        planKalendare(kalendarHlavickaDto)
                            .then((planPeriodyDtos) => {
                            return udalostiKalendare(kalendarHlavickaDto, planPeriodyDtos);
                        })
                            .then((udalosti) => {
                            // inicializační datumy
                            const initialDate = Pam.toDate(kalendarHlavickaDto.dat_plan_od);
                            const minDate = parseDate(kalendarHlavickaDto.dat_plan_od);
                            const minDateStr = GKalendarFun.dateWithoutTimezone(minDate);
                            const maxDate = parseDate(kalendarHlavickaDto.dat_plan_do);
                            const maxDateStr = GKalendarFun.dateWithoutTimezone(maxDate);
                            // widget kalendáře
                            const kalendar = $.newDiv("kalendarDlePlanu")
                                .appendTo(contentDiv)
                                .gcalendar({
                                initialDate: initialDate,
                                minDate: minDateStr,
                                maxDate: maxDateStr,
                                mode: "content",
                                filterButton: false,
                                //newEvent: akceUpravDen,
                                //buttons: [akceUpravDen],
                                //eventclick(element, data, inlinedialog) {
                                //}
                            })
                                .gcalendar("addEvent", udalosti);
                            def.resolve(kalendar);
                        })
                            .always(() => {
                            cnt.endOperation(guid);
                        });
                    }
                    return def.promise();
                }
                GKalendarFun.zobrazKalendar = zobrazKalendar;
                /** Plán kalendáře (nového nebo existujícího) */
                function planKalendare(kalendarHlavickaDto) {
                    const def = $.Deferred();
                    const ixs_kal = kalendarHlavickaDto.ixs_kal;
                    if (ixs_kal) {
                        planExistujicihoKalendare(kalendarHlavickaDto).done((plan) => {
                            if (plan.length != 0) { // existující data
                                def.resolve(plan);
                            }
                            else { // žádná existující data
                                planNovehoKalendare(kalendarHlavickaDto).done((plan) => {
                                    def.resolve(plan);
                                });
                            }
                        });
                    }
                    else {
                        planNovehoKalendare(kalendarHlavickaDto).done((plan) => {
                            def.resolve(plan);
                        });
                    }
                    return def.promise();
                }
                GKalendarFun.planKalendare = planKalendare;
                /** Plán nového kalendáře*/
                function planNovehoKalendare(kalendarHlavickaDto) {
                    const def = $.Deferred();
                    let planPeriodyDtos = [];
                    const delkaPeriody = kalendarHlavickaDto.per_len;
                    if (delkaPeriody == 7) {
                        // výchozí plán pro délku periody 7 a 40 hodin za týden
                        planPeriodyDtos = [
                            { den: 1, hodin: "8.0000", smena_od_text: "00:00", smena_do_text: "00:00", smena2_od_text: "00:00", smena2_do_text: "00:00", smena_od: 0, smena_do: 0, smena2_od: 0, smena2_do: 0 },
                            { den: 2, hodin: "8.0000", smena_od_text: "00:00", smena_do_text: "00:00", smena2_od_text: "00:00", smena2_do_text: "00:00", smena_od: 0, smena_do: 0, smena2_od: 0, smena2_do: 0 },
                            { den: 3, hodin: "8.0000", smena_od_text: "00:00", smena_do_text: "00:00", smena2_od_text: "00:00", smena2_do_text: "00:00", smena_od: 0, smena_do: 0, smena2_od: 0, smena2_do: 0 },
                            { den: 4, hodin: "8.0000", smena_od_text: "00:00", smena_do_text: "00:00", smena2_od_text: "00:00", smena2_do_text: "00:00", smena_od: 0, smena_do: 0, smena2_od: 0, smena2_do: 0 },
                            { den: 5, hodin: "8.0000", smena_od_text: "00:00", smena_do_text: "00:00", smena2_od_text: "00:00", smena2_do_text: "00:00", smena_od: 0, smena_do: 0, smena2_od: 0, smena2_do: 0 },
                            { den: 6, hodin: "0.0000", smena_od_text: "00:00", smena_do_text: "00:00", smena2_od_text: "00:00", smena2_do_text: "00:00", smena_od: 0, smena_do: 0, smena2_od: 0, smena2_do: 0 },
                            { den: 7, hodin: "0.0000", smena_od_text: "00:00", smena_do_text: "00:00", smena2_od_text: "00:00", smena2_do_text: "00:00", smena_od: 0, smena_do: 0, smena2_od: 0, smena2_do: 0 },
                        ];
                    }
                    else {
                        planPeriodyDtos = planDleDelkyPeriody(kalendarHlavickaDto);
                    }
                    def.resolve(planPeriodyDtos);
                    return def.promise();
                }
                /** Plán existujícího kalendáře*/
                function planExistujicihoKalendare(kalendarHlavickaDto) {
                    const def = $.Deferred();
                    let planPeriodyDtos = [];
                    const GUTILS_DATETIME = Gordic.Utils.DateTime;
                    const dat_per_poc = Pam.toDate(kalendarHlavickaDto.dat_per_poc);
                    const dat_plan_od = Pam.toDate(kalendarHlavickaDto.dat_plan_od);
                    const per_len = kalendarHlavickaDto.per_len;
                    const poc_hodin_kr = parseDecimal(kalendarHlavickaDto.poc_hodin_kr);
                    let odPer = new Date();
                    let doPer = new Date();
                    // datum počátku periody je před začátkem kalendáře
                    if (dat_per_poc < dat_plan_od) {
                        // datum začátku periody
                        odPer = GUTILS_DATETIME.addDays(dat_per_poc, per_len);
                        while (odPer < dat_per_poc) {
                            // datum začátku periody
                            odPer = GUTILS_DATETIME.addDays(odPer, per_len);
                        }
                        // datum konce periody
                        doPer = GUTILS_DATETIME.addDays(odPer, per_len - 1);
                    }
                    else {
                        // od data periody po délku periody
                        odPer = dat_per_poc;
                        doPer = GUTILS_DATETIME.addDays(odPer, per_len - 1);
                    }
                    Gordic.Isl.PamKalendarDen.list({
                        filters: {
                            ixs_kal: kalendarHlavickaDto.ixs_kal,
                            dat_od: odPer,
                            dat_do: doPer,
                        }
                    })
                        .getData()
                        .done(result => {
                        planPeriodyDtos = result.map(({ hod_den, smena_od, smena_do, smena2_od, smena2_do }, index) => ({
                            den: (index + 1),
                            hodin: parseDecimal(hod_den).div(poc_hodin_kr).toFixed(12), // výsledné hodiny jsou hod_den děleno poc_hodin_kr, zaokrouhleno na 12 des. místa
                            smena_od: smena_od,
                            smena_do: smena_do,
                            smena2_od: smena2_od,
                            smena2_do: smena2_do,
                            smena_od_text: numtoHHMM(smena_od),
                            smena_do_text: numtoHHMM(smena_do),
                            smena2_od_text: numtoHHMM(smena2_od),
                            smena2_do_text: numtoHHMM(smena2_do),
                        }));
                        def.resolve(planPeriodyDtos);
                    });
                    return def.promise();
                }
                /** Plán neexistujícího kalendáře dle délky periody v hlavičce kalendáře */
                function planDleDelkyPeriody(kalendarHlavickaDto) {
                    const delkaPeriody = kalendarHlavickaDto.per_len;
                    var plan = [];
                    for (let i = 1; i <= delkaPeriody; i++) {
                        const radek = { den: i, hodin: "0", smena_od_text: "00:00", smena_do_text: "00:00", smena2_od_text: "00:00", smena2_do_text: "00:00", smena_od: 0, smena_do: 0, smena2_od: 0, smena2_do: 0 };
                        plan.push(radek);
                    }
                    return plan;
                }
                function udalostiKalendare(kalendarHlavickaDto, planPeriodyDtos) {
                    const def = $.Deferred();
                    // události pro kalendář
                    const nepracovni = dnyUdalosti(WebClient.GKalendarTypDneEnum.Nepracovni, kalendarHlavickaDto, planPeriodyDtos);
                    const pracovni = dnyUdalosti(WebClient.GKalendarTypDneEnum.Pracovni, kalendarHlavickaDto, planPeriodyDtos);
                    const svatky = dnyUdalosti(WebClient.GKalendarTypDneEnum.Svatek, kalendarHlavickaDto, planPeriodyDtos);
                    // nepracovní
                    const udalostNepracovniDny = {
                        active: true,
                        name: "jres:27841572", //RC 27841572 : Nepracovní dny
                        data: nepracovni,
                        customClass: "warning",
                        itemTemplate: (options, event) => {
                            options.dat_od = event.dat_od;
                            options.dat_do = event.dat_do;
                            options.cely_den = event.cely_den;
                            options.title = event.nazev;
                            options.text = event.poznamka;
                            options.color = "warning";
                            options.hideDateTime = true;
                            options.data = event;
                            return options;
                        }
                    };
                    // pracovní
                    const udalostPracovniDny = {
                        active: true,
                        name: "jres:27841573", //RC 27841573 : Pracovní dny
                        data: pracovni,
                        customClass: "info",
                        itemTemplate: (options, event) => {
                            options.dat_od = event.dat_od;
                            options.dat_do = event.dat_do;
                            options.cely_den = event.cely_den;
                            options.title = event.nazev;
                            options.text = event.poznamka;
                            options.color = "info";
                            options.hideDateTime = true;
                            options.data = event;
                            return options;
                        }
                    };
                    // svátky
                    const udalostSvatky = {
                        active: true,
                        name: "jres:27841574", //RC 27841574 : Svátky
                        data: svatky,
                        customClass: "important",
                        itemTemplate: (options, event) => {
                            options.dat_od = event.dat_od;
                            options.dat_do = event.dat_do;
                            options.cely_den = event.cely_den;
                            options.title = event.nazev;
                            options.text = event.poznamka;
                            options.color = "important";
                            options.hideDateTime = true;
                            options.data = event;
                            return options;
                        }
                    };
                    def.resolve([udalostNepracovniDny, udalostPracovniDny, udalostSvatky]);
                    return def.promise();
                }
                /** Vytvoří pole dnů pro událost dny kalendáře dle typu, hlavičky a plánu */
                function dnyUdalosti(typDne, kalendarHlavickaDto, planKalendare) {
                    const GUTILS_DATETIME = Gordic.Utils.DateTime;
                    const ixs_kal = kalendarHlavickaDto.ixs_kal;
                    const dat_per_poc = Pam.toDate(kalendarHlavickaDto.dat_per_poc);
                    const dat_plan_od = Pam.toDate(kalendarHlavickaDto.dat_plan_od);
                    const dat_plan_do = Pam.toDate(kalendarHlavickaDto.dat_plan_do);
                    //const poc_hodin_kr = parseDecimal(kalendarHlavickaDto.poc_hodin_kr!)
                    const per_len = kalendarHlavickaDto.per_len;
                    // délka plánu od data počátku periody do konce kalendáře
                    const delkaPlanu = GUTILS_DATETIME.diff(dat_per_poc, dat_plan_do, "days") + 1;
                    // počet opakování zaokrouhleno na horní celou část
                    const pocetOpakovaniPeriody = Math.ceil(delkaPlanu / per_len);
                    // naklonování plánu periody na celou platnost plánu (delší)
                    const planHodinyCely = [].concat(...new Array(pocetOpakovaniPeriody).fill(planKalendare));
                    const dnyKalendare = [];
                    let pocetDniPredZacatkemPeriody = 0;
                    // datum počátku periody je před začátkem kalendáře
                    if (dat_per_poc < dat_plan_od) {
                        // počet dní od začátku periody do začátku kalendáře
                        pocetDniPredZacatkemPeriody = GUTILS_DATETIME.diff(dat_per_poc, dat_plan_od, "days");
                    }
                    let pruchod = pocetDniPredZacatkemPeriody;
                    let datAkt = dat_plan_od;
                    while (datAkt <= dat_plan_do) {
                        const planRadek = planHodinyCely[pruchod];
                        const hodinyZaDenZPlanu = parseDecimal(planRadek.hodin);
                        switch (typDne) {
                            case WebClient.GKalendarTypDneEnum.Nepracovni: // nepracovní den
                                // pro nulové hodiny
                                if (hodinyZaDenZPlanu.eq(0)) {
                                    // přidat den
                                    const den = denUdalosti(typDne, datAkt, planRadek, ixs_kal);
                                    dnyKalendare.push(den);
                                }
                                break;
                            case WebClient.GKalendarTypDneEnum.Pracovni: // pracovní den
                                // pro nenulové hodiny
                                if (!hodinyZaDenZPlanu.eq(0)) {
                                    // přidat den
                                    const den = denUdalosti(typDne, datAkt, planRadek, ixs_kal);
                                    dnyKalendare.push(den);
                                }
                                break;
                            case WebClient.GKalendarTypDneEnum.Svatek: // svátek
                                const den = Pam.dateDen(datAkt);
                                const mesic = Pam.dateMesic(datAkt);
                                const rok = Pam.dateRok(datAkt);
                                // je svátek
                                if (Pam.jeSvatekDMY(den, mesic, rok)) {
                                    // přidat den
                                    const den = denUdalosti(typDne, datAkt, planRadek, ixs_kal);
                                    dnyKalendare.push(den);
                                }
                                break;
                            default:
                                break;
                        }
                        pruchod = pruchod + 1;
                        datAkt = GUTILS_DATETIME.addDays(datAkt, 1);
                    }
                    return dnyKalendare;
                }
                /** den pro událost kalendáře dle typu, dne a hodin */
                function denUdalosti(typDne, den, plan, ixs_kal) {
                    const hodinyDec = parseDecimal(plan.hodin);
                    // hodiny děleno krácení, na 4 des. místa
                    const hodinyZobr = hodinyDec.toFixed(4);
                    return (typDne == WebClient.GKalendarTypDneEnum.Pracovni) ? // pracovní
                        {
                            ixx: ixs_kal,
                            dat_od: den,
                            dat_do: den,
                            cely_den: 0,
                            nazev: parseDate(den).toLocaleDateString(),
                            poznamka: String.Format("Pracovní den: {0} hodin ({1}–{2}, {3}–{4})", hodinyZobr, plan.smena_od_text?.toString(), plan.smena_do_text?.toString(), plan.smena2_od_text?.toString(), plan.smena2_do_text?.toString()),
                        }
                        : (typDne == WebClient.GKalendarTypDneEnum.Nepracovni) ? // nepracovní
                            {
                                ixx: ixs_kal,
                                dat_od: den,
                                dat_do: den,
                                cely_den: 0,
                                nazev: parseDate(den).toLocaleDateString(),
                                poznamka: String.Format("Nepracovní den: {0} hodin ({1}–{2}, {3}–{4})", hodinyZobr, plan.smena_od_text?.toString(), plan.smena_do_text?.toString(), plan.smena2_od_text?.toString(), plan.smena2_do_text?.toString()),
                            }
                            : (typDne == WebClient.GKalendarTypDneEnum.Svatek) ? // svátek
                                {
                                    ixx: ixs_kal,
                                    dat_od: den,
                                    dat_do: den,
                                    cely_den: 0,
                                    nazev: parseDate(den).toLocaleDateString(),
                                    poznamka: String.Format("Svátek: {0} hodin", hodinyZobr)
                                } : {};
                }
                /** převod čísla z hodin a minut (HOD_MIN = (HOD * 60) + MIN) na řetězec HH:MM*/
                function numtoHHMM(hodMinNum) {
                    let vystup = "";
                    // Rozkládá se algoritmem MIN = MOD(HOD_MIN, 60), HOD = (HOD_MIN - MIN) / 60.
                    const minNum = hodMinNum % 60;
                    const hodNum = (hodMinNum - minNum) / 60;
                    vystup = Gordic.Pam.LPAD(hodNum, 2, "0") + ":" + Gordic.Pam.LPAD(minNum, 2, "0");
                    return vystup;
                }
                GKalendarFun.numtoHHMM = numtoHHMM;
                /** převod čísla z řetězce HH:MM na číslo HOD_MIN = (HOD * 60) + MIN */
                function HHMMtonum(hhmm) {
                    let vystup;
                    const hodiny = Pam.toNumber(hhmm.slice(0, 2)); // první 2 znaky
                    const minuty = Pam.toNumber(hhmm.slice(-2)); // poslední 2 znaky
                    vystup = hodiny * 60 + minuty;
                    return vystup;
                }
                GKalendarFun.HHMMtonum = HHMMtonum;
                /**
                 * Vytvoří pole dnů pro uložení dnů kalendáře podle jedné periody (planKalendare).
                 * Perioda začíná v dat_per_poc, generuje se od dat_plan_od do dat_plan_do.
                 * Každý den je určen podle cyklického plánu periody (pracovní/nepracovní, počet hodin).
                 * Algoritmus je ověřen na:
                 *  - dat_per_poc: 30.12.2024
                 *  - dat_plan_od: 1.1.2025
                 *  - dat_plan_do: 31.12.2025
                 *  - perioda: [8,8,8,8,8,0,0]
                 */
                function dnyKalendareProUlozeni(kalendarHlavickaDto, planKalendare) {
                    const GUTILS_DATETIME = Gordic.Utils.DateTime;
                    // Načtení vstupních dat
                    const dat_per_poc = Pam.toDate(kalendarHlavickaDto.dat_per_poc); // počátek periody
                    const dat_plan_od = Pam.toDate(kalendarHlavickaDto.dat_plan_od); // od kdy generovat
                    const dat_plan_do = Pam.toDate(kalendarHlavickaDto.dat_plan_do); // dokdy generovat
                    const per_len = kalendarHlavickaDto.per_len; // délka periody
                    const dnyKalendare = [];
                    // Offset do periody: kolik dní od počátku periody je první den generování
                    // Např. 30.12.2024 -> 1.1.2025 = offset 2
                    const offset = GUTILS_DATETIME.diff(dat_per_poc, dat_plan_od, "days");
                    let datAkt = dat_plan_od;
                    let pruchod = 0;
                    while (datAkt <= dat_plan_do) {
                        // Index do periody (cyklicky podle délky periody)
                        // Vždy kladný, správně cykluje i při offsetu
                        const indexPeriody = ((offset + pruchod) % per_len + per_len) % per_len;
                        // Získání plánu pro aktuální den
                        const denPlanu = planKalendare[indexPeriody];
                        const hodinyZaDenZPlanu = parseDecimal(denPlanu.hodin);
                        const poc_hodin_kr = parseDecimal(kalendarHlavickaDto.poc_hodin_kr);
                        const hodinyUlozeni = hodinyZaDenZPlanu.mul(poc_hodin_kr);
                        // Zjištění dne, měsíce, roku pro svátky
                        const den = Pam.dateDen(datAkt);
                        const mesic = Pam.dateMesic(datAkt);
                        const rok = Pam.dateRok(datAkt);
                        // Sestavení DTO pro aktuální den
                        const denKalendare = {
                            datum: Pam.DateOnlyToJson(datAkt), // je potřeba oříznout časovou složku!!!! jinak při ukládání na c# straně dojde k posunu data třeba pro 30.3.2025
                            priz_prac: (hodinyZaDenZPlanu.eq(0)) ? 200 /* Pam.Interface.GPamPriznakPracovnihoDne.NepracovniDen */ : 100 /* Pam.Interface.GPamPriznakPracovnihoDne.PracovniDen */,
                            priz_svatek: (Pam.jeSvatekDMY(den, mesic, rok)) ? 100 /* Pam.Interface.GPamPriznakSvatku.Svatek */ : 200 /* Pam.Interface.GPamPriznakSvatku.BeznyDen */,
                            priz_odpocinek: 0,
                            hod_den: hodinyUlozeni,
                            smena_od: denPlanu.smena_od,
                            smena_do: denPlanu.smena_do,
                            smena2_od: denPlanu.smena2_od,
                            smena2_do: denPlanu.smena2_do,
                            uvazek_ik: new Decimal(0),
                            ixs_kal: kalendarHlavickaDto.ixs_kal
                        };
                        dnyKalendare.push(denKalendare);
                        pruchod++;
                        datAkt = GUTILS_DATETIME.addDays(datAkt, 1);
                    }
                    return dnyKalendare;
                }
                GKalendarFun.dnyKalendareProUlozeni = dnyKalendareProUlozeni;
                /** oříznutí datumu o časovou zónu */
                GKalendarFun.dateWithoutTimezone = (date) => {
                    const tzoffset = date.getTimezoneOffset() * 60000; //offset in milliseconds
                    const withoutTimezone = new Date(date.valueOf() - tzoffset)
                        .toISOString()
                        .slice(0, -1);
                    return withoutTimezone;
                };
            })(GKalendarFun = WebClient.GKalendarFun || (WebClient.GKalendarFun = {}));
        })(WebClient = Pam.WebClient || (Pam.WebClient = {}));
    })(Pam = Gordic.Pam || (Gordic.Pam = {}));
})(Gordic || (Gordic = {}));
//  <FileHeader xmlns="http://www.gordic.cz/shared/file-header/v_1.0.0.0">
