                /**
                 * Vytvoření seznam PPV
                 * @returns
                 */
                sestavSeznamPPV() {
                    const Content = this;
                    const def = $.Deferred();
                    Content._TR("sestavSeznamPPV - begin");
                    Content._TR("sestavSeznamPPV - _seznamPPV.Refresh");
                    Content._seznamPPV.Refresh({ filters: { ixs_esu: Content.Ixsesu, rok_obd_mzdy: Content.Rokobdmzdy, pouzePlatne: Content.Nastaveni.pouzePlatnePpv }, fragments: ["*", "kpi", "vcetneZmenyDetailu"] })
                        .then(() => {
                        Content._TR("sestavSeznamPPV - _seznamPPV.Refresh.then");
                        const row = Content._seznamPPV.SelectedRow;
                        Content.Ixsppv_puv = "";
                        if (row !== null) {
                            Content.Ixsppv = row.ixs_ppv || "";
                            const data = Content._seznamPPV.GridGetData;
                            //const dataSorted = data.sort((a, b) => {
                            //    // dat_od jako řetězec
                            //    const x = new Date(a.dat_od ?? "").toISOString()
                            //    const y = new Date(b.dat_od ?? "").toISOString()
                            //
                            //    // porovnání DESC
                            //    return y.localeCompare(x)
                            //})
                            const vyplatkovePPV = data.filter(item => item.je_to_vyplatkovy).map(x => x.ixs_ppv);
                            switch (vyplatkovePPV.length) {
                                case 0:
                                    console.error("jres:27840415"); //RC 27840415 : Žádný PPV není označen jako výplatkový!
                                    break;
                                case 1:
                                    Content.Ixsppv_puv = vyplatkovePPV[0] || "";
                                    break;
                                default:
                                    console.error("jres:27840416", vyplatkovePPV); //RC 27840416 : Více výplatkových PPV v měsíci!
                                    Content.Ixsppv_puv = vyplatkovePPV[0] || "";
                                    break;
                            }
                        }
                        Content._TR("sestavSeznamPPV (Ixsppv ={0} Ixsppv_puv ={1}) - resolved", Content.Ixsppv, Content.Ixsppv_puv);
                        def.resolve();
                    })
                        .catch(() => {
                        Content._TR("sestavSeznamPPV - rejected");
                        def.reject();
                        throw new GError("jres:27340314"); //RC 27340314 : Nepodařilo se sestavit seznam PPV
                    });
                    return def.promise();
                }
