                /**
                * Sestavení KPI items - doplnění akcí do KPI ze serveru
                * @param kpiItems
                * @returns položky pro KPIpanel
                */
                SestavKpiItems(kpiItems) {
                    const Content = this;
                    const result = [];
                    let i = 0;
                    for (i = 0; i < kpiItems.length; ++i) { // postupně si projdu všechny položky
                        const kpiIn = kpiItems[i];
                        const atom = {};
                        // doplním akce
                        switch (kpiIn.name) {
                            case "kpiZpusobVypoctuZP":
                                atom.action = Gordic.Pam.Actions.notImplemented(Content);
                                break;
                            case "kpiZpusobVypoctuSP":
                                atom.action = Gordic.Pam.Actions.notImplemented(Content);
                                break;
                            default: console.error("Neznámá KPI položka: " + kpiIn.name);
                        }
                        // barevný význam
                        switch (Gordic.Pam.toString(kpiIn.meaning)) {
                            case "positive":
                                atom.meaning = "positive";
                                break;
                            case "negative":
                                atom.meaning = "negative";
                                break;
                            default:
                                atom.meaning = "neutral";
                                break;
                        }
                        atom.name = (kpiIn.name || "");
                        atom.actionOnTitle = true;
                        atom.textVisible = true;
                        atom.title = Gordic.Pam.toString(kpiIn.title);
                        atom.titlePosition = "left";
                        atom.tooltip = kpiIn.tooltip;
                        atom.chartVisible = true;
                        atom.displayLabels = false;
                        atom.displayLegend = false;
                        atom.value = (kpiIn.value) ? Gordic.Pam.toNumber(kpiIn.value) : null;
                        atom.value = "";
                        atom.size = "small";
                        atom.isCurrency = false;
                        atom.chartType = "valueCard";
                        if (kpiIn.icon)
                            atom.icon = kpiIn.icon;
                        atom.titlePosition = "top";
                        atom.text = Gordic.Pam.toString(kpiIn.text); // první řádek
                        atom.unit = Gordic.Pam.toString(kpiIn.valueStr); // druhý řádek
                        result[i] = new GObservableObject(atom);
                    }
                    return result;
                }
