                /**
                * Sestavení akcí
                */
                vytvorAkce() {
                    const Content = this;
                    const Akce = Content.actions;
                    Akce.add({
                        name: GHromadneAkce_1.NazvyAkci.dvojklik, captionVisible: "never",
                        run: () => {
                            // získání ixs_esu z vybraného řádku
                            const ixs_esu = Pam.getVal(Pam.GridSelectedRow("seznamDIV"), null, "ixs_esu");
                            if (!ixs_esu)
                                return;
                            // vyhledání osoby v poli výsledků
                            const isl_result = Content.isl_results.find(item => Gordic.Pam.getVal(item, '', "osoba", "ixs_esu") === ixs_esu);
                            if (!isl_result)
                                return;
                            // získání výsledku SPG
                            const spg_result = isl_result.spg_result;
                            if (!spg_result)
                                return;
                            // získání extra dat => detailní seznam chyb
                            if (spg_result.extra_data) {
                                const form = new Gordic.Forms.Form({ layoutDescriptor: "L1M1S1 L-0-12-0, M-0-12-0, S-0-12-0" })
                                    .addSection()
                                    .addField("ggrid", "", {
                                    customClass: "detail",
                                    data: spg_result.extra_data,
                                    renderMode: "auto", // auto, all-at-once, paged-sync, paged-async
                                    columnMode: "fit", // fit, full
                                    navigationMode: "row", // row, cell
                                    profileVisible: false,
                                    showTopPanel: false, showBottomPanel: false, showHeaderRow: true,
                                    columns: new Gordic.Pam.Columns().SestavSloupce([
                                        { coltype: Gordic.Pam.PamColumnType.icon_vysledek_kontroly, colTemplate: { name: "int_1" } },
                                        {
                                            coltype: Gordic.Pam.PamColumnType.text, colTemplate: {
                                                name: 'text', customClass: 'left', caption: 'Text', width: 750,
                                                cellTemplate: (metarow) => `${metarow.char_1} ${metarow.char_2} ${metarow.char_3}`,
                                            }
                                        },
                                    ])
                                });
                                const dialogOptions = { width: 800, height: 200, title: `Detail: ${isl_result.osoba.nazev}` };
                                const dialog = Gordic.Pam.Forms.prototype.WindowFromFrmModal(form, dialogOptions, Content, spg_result.extra_data);
                            }
                        }
                    });
                    Akce.add({
                        name: GHromadneAkce_1.NazvyAkci.seznamKontrolAktualizovat,
                        icon: Gordic.Pam.Icons.aktualizovat,
                        caption: "jres:27840017", //RC 27840017 : Aktualizovat
                        tooltip: "jres:27841719", //RC 27841719 : Aktualizovat seznam kontrol
                        captionVisible: "never",
                        run: () => {
                            Content.seznamKontrol.Refresh();
                        }
                    });
                    Akce.add({
                        name: GHromadneAkce_1.NazvyHromadnychAkci.vykonatKontrolyKrok2,
                        icon: Gordic.Pam.Icons.kch,
                        caption: "jres:27841720", //RC 27841720 : Spustit kontrolu
                        tooltip: "jres:27841721", //RC 27841721 : Spustit vybranou kontrolu
                        run: () => {
                            const radek = Content.seznamKontrol.SelectedRow;
                            if (radek) {
                                const json = {
                                    DtoOsob: Content._DtoOsob, // aktuální osoba
                                    Rokobdmzdy: PAM_CACHE.rokobdlogin, // počítat přihlášené období
                                    Akce: Pam.TypyAkci.kch2_krok,
                                    // TitulekOkna: `${radek.nazev} (${radek.ixs_kch})`,   
                                    hlavickaKontroly: radek, // řádek hlavičky kontroly
                                };
                                Content.navigate("Gordic.Pam.WebClient.Controls.GHromadneAkceControl", json)
                                    .on("close", function (ev, retVal) {
                                });
                            }
                        }
                    });
                }
