                TransformujFiltr(filterIn) {
                    /// <summary> Transformace fitru, abych jej mohl použít na serveru </summary>
                    /// <param name="filterIn" type="Object">Objekt se zadanými hodnotami, jak je zadal uživatel</param>
                    /// <returns type="Object"> List<GDynamickaMaskaDto> </returns>
                    let filterOut = [];
                    let index = 0;
                    for (let i = 0, keys = Object.keys(filterIn), l = keys.length; i < l; ++i) {
                        let kod_udaje_txt = keys[i];
                        let data = filterIn[keys[i]];
                        let tData = data !== null ? data.toString().toUpperCase() : "";
                        if (tData.length > 0) { // pokud je něco vyplněno ...
                            switch (kod_udaje_txt) {
                                case "inteligent_filter":
                                    if (tData.length == 12) { // 12 znaků by mo být PID
                                        switch (tData.substring(4, 3)) // zjisím zjistit jakého je typu
                                         {
                                            case "SE0":
                                            case "SE1":
                                            case "SE2":
                                            case "SE3":
                                                // Identifikátor ESU
                                                filterOut[index] = { kod_udaje: "ixs_esu", operator_masky: "=", hodnota_masky: [] };
                                                filterOut[index]["hodnota_masky"][0] = data;
                                                break;
                                            case "X00":
                                            case "X02":
                                                // PID dokladu
                                                filterOut[index] = { kod_udaje: "ixp", operator_masky: "=", hodnota_masky: [] };
                                                filterOut[index]["hodnota_masky"][0] = data;
                                                break;
                                            case "BAD":
                                                // Tiskový PID dokladu
                                                break;
                                            default:
                                                filterOut[index] = { kod_udaje: kod_udaje_txt, operator_masky: "=", hodnota_masky: [] };
                                                filterOut[index]["hodnota_masky"][0] = data;
                                                break;
                                        }
                                    }
                                    else {
                                        filterOut[index] = { kod_udaje: kod_udaje_txt, operator_masky: "=", hodnota_masky: [] };
                                        filterOut[index]["hodnota_masky"][0] = data;
                                    }
                                    break;
                                case "ixp":
                                    filterOut[index] = { kod_udaje: kod_udaje_txt, operator_masky: "=", hodnota_masky: [] };
                                    filterOut[index]["hodnota_masky"][0] = data;
                                    console.log("ixp hodnota masky: " + data);
                                    break;
                                case "ixs_esu":
                                    filterOut[index] = { kod_udaje: kod_udaje_txt, operator_masky: "=", hodnota_masky: [] };
                                    filterOut[index]["hodnota_masky"][0] = data;
                                    console.log("ixs_esu hodnota masky: " + data);
                                    break;
                                case "ico":
                                    filterOut[index] = { kod_udaje: kod_udaje_txt, operator_masky: "=", hodnota_masky: [] };
                                    filterOut[index]["hodnota_masky"][0] = data;
                                    console.log("ico hodnota masky: " + data);
                                    break;
                                case "nks":
                                    filterOut[index] = { kod_udaje: kod_udaje_txt, operator_masky: "=", hodnota_masky: [] };
                                    filterOut[index]["hodnota_masky"][0] = data;
                                    console.log("nks hodnota masky: " + data);
                                    break;
                                case "nazev_esu": // políčka obsahující i operátor
                                    filterOut[index] = { kod_udaje: kod_udaje_txt, operator_masky: "=", hodnota_masky: [] };
                                    filterOut[index]["operator_masky"] = data.o;
                                    filterOut[index]["hodnota_masky"][0] = data.v;
                                    break;
                                default:
                                    console.error("Neobsloužený klíč masky: " + kod_udaje_txt);
                                    break;
                            }
                            index++; // vložil jsem prvek, je nutno zvýšit čítač
                        }
                    }
                    return filterOut;
                } // TransformujFiltr
