                prevzitDoklad() {
                    /// <summary>
                    /// Převzetí dokladu
                    /// </summary>
                    let Content = this;
                    let def = $.Deferred();
                    let text = "";
                    console.log("prevzitDoklad: start");
                    Content.beginOperation(); // nahodím točíko
                    Gordic.Pam.CallWithPromise("PrijmiDokladDoMezd", { ixp: Content["Ixp"] })
                        .then(function (data) {
                        let spgresult = data;
                        if (spgresult.op_err_code === 0) { // pokud nedošlo k chybě
                            console.log("prevzitDoklad: done OK");
                            Content.endOperation(); // abych ukončil točítko
                            def.resolve("Doklad byl úspěšně převzat.");
                        }
                        else {
                            text = "Chyba: ";
                            if (spgresult.op_err_txt)
                                text = text + spgresult.op_err_txt.trim();
                            console.log("prevzitDoklad: done chyba text=" + text);
                            Content.showFlash({ label: text, timer: 10000, customClass: 'g-state-error' });
                            Gordic.Pam.LogujSpgChybu(spgresult);
                            Content.endOperation(); // abych ukončil točítko
                            def.reject(text);
                        }
                        return def.promise();
                    })
                        .catch(() => {
                        console.log("prevzitDoklad: fail");
                        text = "Chyba při příjmu dokladu";
                        Content.endOperation(); // abych ukončil točítko
                        def.reject(text);
                    });
                    Content.endOperation(); // abych ukončil točítko
                    console.log("prevzitDoklad: end");
                }
