                                        //        Content.id = <string>ctx.cellInfo.data["id"];
                                        //        Content.text = <string>ctx.cellInfo.data["text"];
                                        //        Content.AktualizujRekap();
                                        //        $("#" + Content.divVyberName).remove(); // po výběru DIV zruším  abych je mohl recyklovat                                            
                                        //        wiz.setStep(wiz.getStep(Content) + 1); // a přejdu na další krok                                            
                                        //    }
