                        let radky = Content._seznamPracovist.SelectedRows;
                        if (radky !== null) {
                            let pidyESU = radky.map(function (x) { return x["ixs_pra"]; });
                            return pidyESU;
                        }
                        ; // získání dto dat z gridu a její redukce pouze na jeden prvek ixs_esu
