                /**
                 *  Vyvolání přepočtového dialogu se seznamem osob z více pracovišť
                 */
                prepocetOsob() {
                    let Content = this;
                    let pidyPra = Content.PidyPra(); // seznam pidů pracovišť
                    let maska = [
                        {
                            hodnota_masky: pidyPra,
                            is_multi: true,
                            kod_udaje: "ixs_pra",
                            operator_masky: "IN"
                        },
                        {
                            hodnota_masky: ["true"],
                            is_multi: false,
                            kod_udaje: "neplatneppv",
                            operator_masky: "="
                        },
                    ];
                    const filtr = {
                        rok_obd_mzdy: Content["Rokobdmzdy"],
                        user_filter: (maska == null) ? null : JSON.stringify(maska)
                    };
                    new Pam.DataObject(Content, Pam.DataType.OsobaPAM).List({ filters: filtr })
                        .done(function (osoby) {
                        let dtoOsob = osoby.getRows();
                        const l_oParamsJSON = {
                            DtoOsob: dtoOsob,
                            Rokobdmzdy: Content["Rokobdmzdy"],
                            Akce: Pam.TypyAkci.vyuctovani_vypocet,
                            TitulekOkna: "Přepočet osob za pracoviště"
                        };
                        Content.navigate("Gordic.Pam.WebClient.Controls.GHromadneAkceControl", l_oParamsJSON);
                    });
                }
                /**
                *  Vyvolání výpočtu záloh se seznamem osob z více pracovišť
                */
                prepocetZalohOsob() {
                    let Content = this;
                    let pidyPra = Content.PidyPra(); // seznam pidů pracovišť
                    let maska = [
                        {
                            hodnota_masky: pidyPra,
                            is_multi: true,
                            kod_udaje: "ixs_pra",
                            operator_masky: "IN"
                        },
                        {
                            hodnota_masky: ["true"],
                            is_multi: false,
                            kod_udaje: "neplatneppv",
                            operator_masky: "="
                        },
                    ];
                    const filtr = {
                        rok_obd_mzdy: Content["Rokobdmzdy"],
                        user_filter: (maska == null) ? null : JSON.stringify(maska)
                    };
                    new Pam.DataObject(Content, Pam.DataType.OsobaPAM).List({ filters: filtr })
                        .done(function (osoby) {
                        let dtoOsob = osoby.getRows();
                        const l_oParamsJSON = {
                            DtoOsob: dtoOsob,
                            Rokobdmzdy: Content["Rokobdmzdy"],
                            Akce: Pam.TypyAkci.zalohy_vypocet,
                            TitulekOkna: "Přepočet záloh za pracoviště"
                        };
                        Content.navigate("Gordic.Pam.WebClient.Controls.GHromadneAkceControl", l_oParamsJSON);
                    });
                }
                /**
                 *  Zavolání uzávěrkového objektu pro vybraná pracoviště
                 * */
                UzaverkaPracovist() {
                    let Content = this;
                    let radky = Content._seznamPracovist.SelectedRows;
                    if (radky != null) {
                        let stavyUzaverek = radky.map(function (x) { return x.nazev_kpd; }); // redukce na pole ixs_kpd
                        let stavyUzaverekUnique = stavyUzaverek.filter((v, i, a) => a.indexOf(v) === i); // 
                        if (Gordic.Pam.countProperties(stavyUzaverekUnique) !== 1) {
                            Content.dialogs.warning("Varování", "Při uzávěrce za více pracovišť, je nutné, aby byly všechny ve shodné stavu!\n\Upravte prosím upravte výběr a opakujte");
                        }
                        else {
                            Content.navigate("Gordic.Pam.WebClient.Controls.GUzaverkyControl", { SeznamPracovist: radky })
                                .on("close", function (ev, retVal) {
                                Content._seznamPracovist.Refresh({ rok_obd_mzdy: Content["Rokobdmzdy"] }); // občerstvení seznamu pracovišť, abych aktualizovat stavy uzávěrek
                            });
                        }
                    }
                }
                /**
                   * Vytvoření menubaru
                * */
                vytvorBar() {
                    let Content = this;
                    let Akce = Content.actions;
                    Content.menuBar(Content.actions.createBar([
                        GSeznamPracovist_1.NazvyAkci.ZobrazSeznamOsobAct + "*",
                        GSeznamPracovist_1.NazvyAkci.tiskAct + "*",
                        GSeznamPracovist_1.NazvyAkci.prepoctiOsobyAct + "*",
                        GSeznamPracovist_1.NazvyAkci.prepoctiZalohyOsobyAct + "*",
                        GSeznamPracovist_1.NazvyAkci.actUzaverkaPracovistAct + "*",
                        GSeznamPracovist_1.NazvyAkci.UcetniProfilAct,
                        "<" + GSeznamPracovist_1.NazvyAkci.Aktualizovat + "*", // aktualizace seznamu pracovišť
                    ]));
                }
