                /**
                 * Přímý tisk sestavy zadané pomocí ixs_alv popř. ixs_alf. Neotevírá se okno se stromem sestav.
                 * @param ixsAlv ixs_alv definice sestavy
                 * @param ixsAlf ixs_alf formát sestavy
                 */
                vygenerujSestavu(parentContent, ixsAlv, ixsAlf) {
                    let Content = this;
                    var def = $.Deferred();
                    let serverParameterMethod = "";
                    if (Content.mnozina == "PPV")
                        serverParameterMethod = "Gordic.Pam.Client.GTisky:ParametrySestavyPPV";
                    if (Content.mnozina == "ESU")
                        serverParameterMethod = "Gordic.Pam.Client.GTisky:ParametrySestavyESU";
                    if (Content.mnozina == "PRA")
                        serverParameterMethod = "Gordic.Pam.Client.GTisky:ParametrySestavyPRA";
                    if (Content.mnozina == "ALL")
                        serverParameterMethod = "Gordic.Pam.Client.GTisky:ParametrySestavyALL";
                    if (ixsAlv != null) {
                        //Vytvořím ReportObject z definice sestavy 
                        Content.isl.PamSestava.read({ ixs_alv: ixsAlv || "" }).getData()
                            .done((sestavaInfo) => {
                            const reportObj = {
                                ixs_alv: sestavaInfo.ixs_alv || "",
                                id_ses: sestavaInfo.id_ses || "",
                                ixs_alf: (Pam.isEmpty(ixsAlf) ? sestavaInfo.ixs_frm : ixsAlv) || "",
                                ixs_str: sestavaInfo.ixs_str || "",
                                nazev: sestavaInfo.nazev_sestavy || "",
                                //platnost: sestavaInfo.rokmes_od || "",      //pokud sem dám pouze platnost od, tak výsledný select nenajde správně ALF (ginsfrm.rokmes_od <= '199801' AND ginsfrm.rokmes_do >= '199801' AND )
                                platnost: Pam.RokObdMzdy2RokMes(Content["Rokobdmzdy"]),
                                //tema: sestavaInfo.tema || "",
                                //outputStyle: 'PDF',
                                serverParameterMethod: serverParameterMethod,
                                customDto: {
                                    char_1: ixsAlv, // do customDTO.char_1 si dávám ixs_alv
                                    char_2: !Pam.isEmpty(ixsAlf) ? ixsAlf : "" // do customDTO.char_2 si dávám ixs_alf
                                }
                            };
                            const PAM_REPORTS = new Gordic.Pam.Reports(parentContent);
                            def.resolve(PAM_REPORTS.GenerujSestavuNaPozadi(reportObj));
                        })
                            .fail(() => def.resolve(null));
                    }
                    else {
                        def.resolve();
                    }
                    return def.promise();
                }
                /**
                * Sestavení tiskové akce pro konkrétní sestavu - zatím nepoužito (použit přímý tisk sestavy)
                * @param {string} nazevAkce Název akce
                * @param {string} caption Text v menu
                * @param {string} tooltip Text tooltipu
                * @param {string} tema Tiskové téma
                * @param {string} ixsAlv ixs_alv pro omezení nabídky sestav na konkrétní sestavu
                * @param {string} ixsFrm ixs_frm pro omezení na konkrétní formát konkrétní sestavy
                */
                vytvorAkciTisk(nazevAkce, caption, tooltip, tema, ixsAlv, ixsFrm) {
                    let Content = this;
                    let Akce = Content.actions;
                    let customDTO = {};
                    let serverParameterMethod = "";
                    if (Content.mnozina == "PPV")
                        serverParameterMethod = "Gordic.Pam.Client.GTisky:ParametrySestavyPPV";
                    if (Content.mnozina == "ESU")
                        serverParameterMethod = "Gordic.Pam.Client.GTisky:ParametrySestavyESU";
                    if (Content.mnozina == "PRA")
                        serverParameterMethod = "Gordic.Pam.Client.GTisky:ParametrySestavyPRA";
                    if (Content.mnozina == "ALL")
                        serverParameterMethod = "Gordic.Pam.Client.GTisky:ParametrySestavyALL";
                    if (!Pam.isEmpty(Content["ikc"]))
                        customDTO.ikc = Content["ikc"];
                    if (!Pam.isEmpty(ixsAlv))
                        customDTO.char_1 = ixsAlv;
                    if (!Pam.isEmpty(ixsFrm))
                        customDTO.char_2 = ixsFrm;
                    let par = {
                        name: nazevAkce,
                        tema: tema,
                        title: caption,
                        serverParameterMethod: serverParameterMethod,
                        fullScreen: true,
                        keepOpen: true, // Řídí zavření okna sestav po generování sestavy. Pokud je true, nechá okno po vygenerování otevřené.
                        selectReportOnly: false,
                        parentContent: Content,
                        customDto: customDTO,
                        tooltip: tooltip,
                        enabled: true,
                        favorite: true,
                        schedulingDisabled: true, // Schova tlačítko pro odložené zpracování sestavy
                        initFolders: false, //složky se nezobrazí
                        serverRestrictionAlvMethod: "Gordic.Pam.Client.GTisky:GetRestrictionForOneAlv",
                        serverRestrictionAlfMethod: "Gordic.Pam.Client.GTisky:GetRestrictionForOneAlf",
                        dialogOpening: function (action) {
                            ((Content.breadcrumbs) || []).push({ caption: tooltip, defaultAction: true }); // přihodím si text tooltipu z položky menu
                            Content.setBreadcrumbs(Content.breadcrumbs);
                            return true;
                        },
                        dialogClosed: function (ev, repInfo) {
                            this.content.tryCloseAllSignificants();
                            ((Content.breadcrumbs) || []).pop(); // odstranění posledního prvku
                            Content.setBreadcrumbs(Content.breadcrumbs); // obnovení breacrumps
                        },
                        reportFinished: function () {
                            //debugger;
                            //TODO: tady bych měl zavolat akce na vygenerování XML popř. odeslání na PVS či uložení do registru výstupů
                            //      použil bych CASE dle nazvu akce a podle toho volal další akce
                        }, // zavolána v momentě, kdy byl report vygenerován a úspěšně skončilo celé workflow
                        //run: function (ev, ctx) {
                        //    Pam.RunAction(Content, nazevAkce)
                        //}
                        // reportGenerated: function () {  debugger; },// Metoda je zavolána v momentě, kdy došlo k vygenerování sestavy
                        // reportCancelled: function () { debugger; } //zavolána v momentě, kdy uživatel zruší generování sestavy
                        // reportSelected: function () { debugger; } //  Metodabude zavolána v momentě, kdy uživatel vybere sestavu nebo klikne na prvek, který v sobě obsahuje skupinu sestav.Rozlišit, zda uživatel klepnul na jeden nebo druhý typ lze pomocí property isReport
                        // reportStarting: function (rep: IGPrintActionReportStarting) { debugger;} // je volána těsně před generováním sestav                    
                        // reportFinished: function () { debugger;} // zavolána v momentě, kdy byl report vygenerován a úspěšně skončilo celé workflow
                    };
                    Akce.add(GAction.createPrintAction(par));
                }
